// The four helpers below build sentences that mix static copy with data. Doing
// it in Go rather than in the template keeps the exact single spaces the German
// copy needs: templ emits a text node per line, and a conditional in the middle
// of a sentence leaves a stray space behind.

func energyAgreedHint(tariff EnergyTariffView) string {
	if tariff.HasAgreed {
		return "Steht auf Ihrer Netzrechnung. Der Entwurf bemisst mindestens 20 % davon. Leer lassen, wenn unbekannt."
	}
	if tariff.AgreedHint == "" {
		return "Leer lassen, wenn unbekannt."
	}
	return tariff.AgreedHint + " Leer lassen, wenn unbekannt."
}

func energyCostModelSentence(freeUntil string) string {
	scope := "zwölf Monate kostenlos"
	if freeUntil != "" {
		scope = "kostenlos bis " + freeUntil
	}
	return "voller Produktumfang " + scope + ", danach nach heutigem Modell 12 € pro Jahr. Bestehende Pilot-Enddaten bleiben erhalten; aktuell gibt es keine Zahlung."
}

func energyMaintenanceMeta(plan EnergyMaintenanceView) string {
	meta := plan.AssetName + " · alle " + strconv.Itoa(plan.IntervalMonths) + " Monate"
	if plan.LastCompleted != "" {
		meta += " · zuletzt " + plan.LastCompleted
	}
	return meta
}

func energyMeasureMeta(measure EnergyMeasureView) string {
	meta := measure.StatusLabel
	if measure.ContactName != "" {
		meta += " · " + measure.ContactName
	}
	if measure.Appointment != "" {
		meta += " · " + measure.Appointment
	}
	return meta
}

var _ = templruntime.GeneratedTemplate
